def _list_inner(cache):
    archive = Archive(manifest, archive_info.id, cache=cache)
    formatter = ItemFormatter(archive, format)
    for item in archive.iter_items(lambda item: matcher.match(item.path)):
        # Apply depth filtering if --depth is specified
        if hasattr(args, 'depth') and args.depth is not None:
            # Calculate depth of the item relative to the archive root
            item_path = item.path.rstrip('/')
            if item_path:  # Not empty path
                depth = item_path.count('/')
            else:
                depth = 0
            # Skip items deeper than specified depth
            if depth > args.depth:
                continue
        sys.stdout.write(formatter.format_item(item, args.json_lines, sort=True))
